import java.util.Arrays;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.atomic.AtomicReference;

public class SolutionTest {
    private static void check(boolean condition, String message) {
        if (!condition) throw new AssertionError(message);
    }

    private static void arrayEquals(String[] expected, String[] actual, String message) {
        if (!Arrays.equals(expected, actual))
            throw new AssertionError(message + ": expected=" + Arrays.toString(expected)
                    + ", actual=" + Arrays.toString(actual));
    }

    private static String repeat(char c, int count) {
        StringBuilder value = new StringBuilder();
        for (int i = 0; i < count; i++) value.append(c);
        return value.toString();
    }

    public static void main(String[] args) throws Exception {
        Solution.clear();
        check(Solution.read("missing") == null, "empty read");
        check(Solution.read(null) == null, "null read");
        check(Solution.read("bad-key") == null, "malformed read");
        String[] empty1 = Solution.snapshot();
        String[] empty2 = Solution.snapshot();
        arrayEquals(new String[0], empty1, "empty snapshot");
        check(empty1 != empty2, "empty snapshots alias");

        check(Solution.write("b2", "two"), "valid write rejected");
        check(Solution.write("A1", ""), "empty value rejected");
        check(Solution.write("a3", repeat('v', 256)), "boundary value rejected");
        check("".equals(Solution.read("A1")), "empty value read incorrectly");
        arrayEquals(new String[]{"A1=", "a3=" + repeat('v', 256), "b2=two"},
                Solution.snapshot(), "snapshot ordering/content");

        check(Solution.write("b2", "updated"), "overwrite rejected");
        check("updated".equals(Solution.read("b2")), "overwrite missing");
        check(!Solution.write(null, "x"), "null key accepted");
        check(!Solution.write("", "x"), "empty key accepted");
        check(!Solution.write(repeat('k', 33), "x"), "long key accepted");
        check(!Solution.write("bad_key", "x"), "punctuated key accepted");
        check(!Solution.write("é", "x"), "non-ASCII key accepted");
        check(!Solution.write("valid", null), "null value accepted");
        check(!Solution.write("valid", repeat('x', 257)), "long value accepted");
        check("updated".equals(Solution.read("b2")), "invalid write mutated ledger");

        String[] exposed = Solution.snapshot();
        String[] independent = Solution.snapshot();
        check(exposed != independent, "snapshots alias");
        exposed[0] = "corrupted";
        check(!"corrupted".equals(Solution.snapshot()[0]), "snapshot exposed ledger state");

        Solution.clear();
        final int threads = 4;
        final int writes = 150;
        CountDownLatch start = new CountDownLatch(1);
        AtomicReference<Throwable> failure = new AtomicReference<>();
        Thread[] workers = new Thread[threads];
        for (int t = 0; t < threads; t++) {
            final int worker = t;
            workers[t] = new Thread(() -> {
                try {
                    start.await();
                    for (int i = 0; i < writes; i++) {
                        String key = "T" + worker + "K" + i;
                        if (!Solution.write(key, Integer.toString(i)))
                            throw new AssertionError("concurrent write rejected");
                        String[] snap = Solution.snapshot();
                        for (int j = 1; j < snap.length; j++)
                            if (snap[j - 1].compareTo(snap[j]) >= 0)
                                throw new AssertionError("incoherent or unsorted snapshot");
                    }
                } catch (Throwable ex) {
                    failure.compareAndSet(null, ex);
                }
            });
            workers[t].start();
        }
        start.countDown();
        for (Thread worker : workers) worker.join();
        if (failure.get() != null) throw new AssertionError("concurrent operation failed", failure.get());
        check(Solution.snapshot().length == threads * writes, "concurrent entries lost");
        for (int t = 0; t < threads; t++)
            for (int i = 0; i < writes; i++)
                check(Integer.toString(i).equals(Solution.read("T" + t + "K" + i)), "wrong concurrent value");

        Solution.clear();
        arrayEquals(new String[0], Solution.snapshot(), "clear failed");
    }
}

